SELECT COUNT(1) FROM "jeecg-boot-os".sys_user_role r
WHERE r.role_id IN('0515710a3d73da87c3d8fad580bc43f6','f6817f48af4fb3af11b9e8bf182f618b')
AND r.USER_ID = #{params.USERID}

SELECT a.*, a.INDEX_ID AS subject_id, REPLACE(REPLACE(REPLACE(a.INDEX_DIMNSN,'1','国库'),'2','地区'),'3','核算主体') AS INDEX_DIMNSN_DSCR, REPLACE(REPLACE(REPLACE(REPLACE(a.INDEX_PERIOD,'1','日指标'),'2','月指标'),'3','季指标'),'4','年指标') AS INDEX_PERIOD_DSCR, CASE WHEN a.INDEX_TYPE ='0' THEN '数值' WHEN a.INDEX_TYPE ='1' THEN '比率' END AS INDEX_TYPE_DSCR, CASE WHEN a.RUN_BATCH_STATUS ='0' THEN '未开始' WHEN a.RUN_BATCH_STATUS ='1' THEN '进行中' WHEN a.RUN_BATCH_STATUS ='2' THEN '已完成' ELSE '' END AS RUN_BATCH_DSCR, COALESCE(f.BUILD_TYPE,'') AS BUILD_TYPE, COALESCE(f.ORIGINAL_DSCR,'') AS ORIGINAL_DSCR, COALESCE(f.ORIGINAL_DSCR_ARRY,'') AS ORIGINAL_DSCR_ARRY, COALESCE(f.INDEX_DSCR,'') AS INDEX_DSCR, COALESCE(f.INDEX_DSCR_ARRY,'') AS INDEX_DSCR_ARRY, f.EXE_DEL, f.EXE_INSERT, COALESCE(f.EXE_SQL,'') AS EXE_SQL, COALESCE(f.EXE_WHERE,'') AS EXE_WHERE, COALESCE(f.HTML_STR,'') AS HTML_STR, COALESCE(aap.app_result, '') AS app_result FROM indicators_lib.lib_index_relation a LEFT JOIN indicators_lib.lib_index_formula f ON a.INDEX_ID=f.ID LEFT JOIN approval.appr_approval aap ON a.INDEX_ID = aap.subject_id WHERE a.INDEX_STATUS ='0' AND f.BUILD_TYPE IS NOT NULL
AND a.PERSONAL_FLAG = '0' AND a.ADD_USERID = #{params.USERID}
AND a.PERSONAL_FLAG = '1'
AND a.INDEX_ID = #{params.INDEX_ID}
AND a.INDEX_NAME LIKE '%${params.INDEX_NAME}%'
AND a.INDEX_TYPE = #{params.INDEX_TYPE}
AND #{params.INDEX_DIMNSN} = ANY(string_to_array(COALESCE(a.INDEX_DIMNSN, ''), ','))
AND #{params.INDEX_PERIOD} = ANY(string_to_array(COALESCE(a.INDEX_PERIOD, ''), ','))
ORDER BY a.ADD_DATE DESC LIMIT ${params.rows} OFFSET ${params.page}

SELECT COUNT(1) FROM indicators_lib.lib_index_relation a LEFT JOIN indicators_lib.lib_index_formula f ON a.INDEX_ID=f.ID WHERE a.INDEX_STATUS ='0' AND f.BUILD_TYPE IS NOT NULL
AND a.PERSONAL_FLAG = '0' AND a.ADD_USERID = #{params.USERID}
AND a.PERSONAL_FLAG = '1'
AND a.INDEX_ID = #{params.INDEX_ID}
AND a.INDEX_NAME LIKE '%${params.INDEX_NAME}%'
AND a.INDEX_TYPE = #{params.INDEX_TYPE}
AND #{params.INDEX_DIMNSN} = ANY(string_to_array(COALESCE(a.INDEX_DIMNSN, ''), ','))
AND #{params.INDEX_PERIOD} = ANY(string_to_array(COALESCE(a.INDEX_PERIOD, ''), ','))

mapper.update:
UPDATE indicators_lib.lib_index_relation
SET
    PERSONAL_FLAG = #{params.PERSONAL_FLAG},
    USER_ID = #{params.MODIFY_USERID},
    MODIFY_DATE = #{params.MODIFY_DATE}
WHERE INDEX_ID = #{params.INDEX_ID}

UPDATE indicators_lib.lib_index_user
SET USER_ID = #{params.MODIFY_USERID}
WHERE INDEX_ID = #{params.INDEX_ID}
